"""Editorially reviewed Angolan Portuguese A1 lessons (first batch).

These lessons replace the generic level templates with topic-specific instruction.
Pronunciation spellings are learner aids, not phonetic transcriptions or a claim
that Angola has one uniform accent.
"""

def _lesson(title, goal, objectives, vocabulary, grammar, expressions, examples,
            conversations, pronunciation, exercises, assessment, speaking,
            summary, homework):
    vocab = [(w, meaning, hint, "—", example) for w, meaning, hint, example in vocabulary]
    return {
        "title": title, "goal": goal, "objectives": objectives,
        "vocabulary": vocab, "grammar": grammar, "expressions": expressions,
        "examples": examples, "conversations": conversations,
        "pronunciation": pronunciation, "exercises": exercises,
        "assessment": assessment, "speaking": speaking,
        "summary": summary, "homework": homework,
    }

